<?php
require_once '../includes/role.php'; requireRole('mechanic'); require_once '../config/database.php'; require_once '../includes/helpers.php'; require_once '../includes/csrf.php';
$bookingId=(int)($_GET['id']??$_POST['booking_id']??0); $m=$pdo->prepare('SELECT id FROM mechanics WHERE user_id=?');$m->execute([$_SESSION['user_id']]);$mechanicId=(int)$m->fetchColumn();
$q=$pdo->prepare("SELECT b.*,u.name customer_name,u.phone,v.plate_number,v.brand,v.model,v.year,v.color,s.name service_name,b.service_price FROM bookings b JOIN users u ON u.id=b.user_id JOIN vehicles v ON v.id=b.vehicle_id JOIN services s ON s.id=b.service_id WHERE b.id=? AND b.mechanic_id=?");$q->execute([$bookingId,$mechanicId]);$booking=$q->fetch(); if(!$booking) exit('Pekerjaan tidak ditemukan.');
$r=$pdo->prepare('SELECT * FROM service_records WHERE booking_id=?');$r->execute([$bookingId]);$record=$r->fetch();
$parts=$record ? $pdo->prepare('SELECT sp.*,p.name,p.part_number FROM service_parts sp LEFT JOIN spareparts p ON p.id=sp.sparepart_id WHERE sp.service_record_id=? ORDER BY sp.id'):null; if($parts){$parts->execute([$record['id']]);$parts=$parts->fetchAll();}else{$parts=[];}
$spares=$pdo->query("SELECT * FROM spareparts WHERE status='active' AND stock>0 ORDER BY name")->fetchAll();$error='';$success='';
$editable = in_array($booking['status'], ['confirmed','waiting','in_progress'], true);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if (!$editable) { $error='Pekerjaan ini sudah ditutup dan tidak dapat diubah lagi.'; } else try{$pdo->beginTransaction();
  if($action==='save'){$inspection=trim($_POST['inspection']??'');$diagnosis=trim($_POST['diagnosis']??'');$actionTaken=trim($_POST['action_taken']??'');$notes=trim($_POST['notes']??'');if($record){$s=$pdo->prepare('UPDATE service_records SET inspection=?,diagnosis=?,action_taken=?,notes=? WHERE id=?');$s->execute([$inspection,$diagnosis,$actionTaken,$notes,$record['id']]);}else{$s=$pdo->prepare('INSERT INTO service_records(booking_id,mechanic_id,inspection,diagnosis,action_taken,notes) VALUES(?,?,?,?,?,?)');$s->execute([$bookingId,$mechanicId,$inspection,$diagnosis,$actionTaken,$notes]);}$s=$pdo->prepare("UPDATE bookings SET status=IF(status IN ('confirmed','waiting','pending'),'in_progress',status) WHERE id=?");$s->execute([$bookingId]);
   log_activity($pdo, 'service_note_saved', 'Mekanik menyimpan catatan pemeriksaan dan pengerjaan.', 'booking', $bookingId);
   $success='Catatan pemeriksaan disimpan.';}
  elseif($action==='add_part'){ $partId=(int)$_POST['sparepart_id'];$qty=(int)$_POST['quantity']; if(!$record){$s=$pdo->prepare('INSERT INTO service_records(booking_id,mechanic_id) VALUES(?,?)');$s->execute([$bookingId,$mechanicId]);$recordId=(int)$pdo->lastInsertId();}else{$recordId=(int)$record['id'];}$s=$pdo->prepare('SELECT price,stock FROM spareparts WHERE id=? AND status="active" FOR UPDATE');$s->execute([$partId]);$part=$s->fetch();if(!$part||$qty<1||$qty>$part['stock'])throw new Exception('Sparepart atau jumlah tidak valid.');$s=$pdo->prepare('INSERT INTO service_parts(service_record_id,sparepart_id,quantity,price) VALUES(?,?,?,?)');$s->execute([$recordId,$partId,$qty,$part['price']]);$s=$pdo->prepare('UPDATE spareparts SET stock=stock-? WHERE id=?');$s->execute([$qty,$partId]);log_activity($pdo, 'sparepart_added', 'Mekanik menambahkan sparepart ke pekerjaan.', 'booking', $bookingId);$success='Sparepart ditambahkan.';}
  elseif($action==='remove_part'){ $partRow=(int)$_POST['part_id'];$s=$pdo->prepare('SELECT sparepart_id,quantity FROM service_parts WHERE id=? AND service_record_id=(SELECT id FROM service_records WHERE booking_id=?) FOR UPDATE');$s->execute([$partRow,$bookingId]);$pr=$s->fetch();if($pr){$s=$pdo->prepare('DELETE FROM service_parts WHERE id=?');$s->execute([$partRow]);$s=$pdo->prepare('UPDATE spareparts SET stock=stock+? WHERE id=?');$s->execute([$pr['quantity'],$pr['sparepart_id']]);}log_activity($pdo, 'sparepart_removed', 'Mekanik menghapus sparepart dari pekerjaan.', 'booking', $bookingId);$success='Sparepart dihapus.';}
  elseif($action==='complete'){ if(!$record) throw new Exception('Simpan catatan pemeriksaan terlebih dahulu sebelum menyelesaikan pekerjaan.'); $hasWorkNote=trim((string)($record['inspection']??''))!=='' || trim((string)($record['diagnosis']??''))!=='' || trim((string)($record['action_taken']??''))!=='' || trim((string)($record['notes']??''))!==''; if(!$hasWorkNote) throw new Exception('Isi minimal satu catatan pemeriksaan, diagnosis, tindakan, atau catatan sebelum menyelesaikan pekerjaan.'); $s=$pdo->prepare("UPDATE bookings SET status='waiting_payment' WHERE id=? AND mechanic_id=? AND status IN ('confirmed','waiting','in_progress')");$s->execute([$bookingId,$mechanicId]);if($s->rowCount()!==1)throw new Exception('Pekerjaan sudah tidak dapat diselesaikan pada status saat ini.');$s=$pdo->prepare('UPDATE service_records SET completed_at=NOW() WHERE booking_id=?');$s->execute([$bookingId]);$s=$pdo->prepare("UPDATE mechanics SET status='available' WHERE id=?");$s->execute([$mechanicId]);
   log_activity($pdo, 'service_completed', 'Mekanik menyelesaikan pekerjaan dan booking masuk tahap pembayaran.', 'booking', $bookingId);
   $n=$pdo->prepare('SELECT user_id FROM bookings WHERE id=?');$n->execute([$bookingId]);$customerUserId=(int)$n->fetchColumn();notify_user($pdo,$customerUserId,'Servis selesai','Pekerjaan kendaraan Anda telah selesai. Silakan lanjutkan ke pembayaran.','success','booking',$bookingId);
   $success='Pekerjaan diselesaikan dan menunggu pembayaran.';}
  $pdo->commit();header('Location: service.php?id='.$bookingId.'&ok='.urlencode($success));exit;
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=servisku_error_message($e);}
}
if(isset($_GET['ok']))$success=$_GET['ok'];$r=$pdo->prepare('SELECT * FROM service_records WHERE booking_id=?');$r->execute([$bookingId]);$record=$r->fetch();$parts=[];if($record){$x=$pdo->prepare('SELECT sp.*,p.name,p.part_number FROM service_parts sp LEFT JOIN spareparts p ON p.id=sp.sparepart_id WHERE sp.service_record_id=? ORDER BY sp.id');$x->execute([$record['id']]);$parts=$x->fetchAll();}
$partsTotal=0;foreach($parts as $partRow){$partsTotal+=(float)$partRow['quantity']*(float)$partRow['price'];}
$grandTotal=(float)$booking['service_price']+$partsTotal;
$statusSteps=[['confirmed','Booking dikonfirmasi'],['in_progress','Sedang dikerjakan'],['waiting_payment','Menunggu pembayaran'],['paid','Selesai']];
$statusOrder=['pending'=>0,'confirmed'=>1,'waiting'=>1,'in_progress'=>2,'waiting_payment'=>3,'paid'=>4,'cancelled'=>-1];
$currentStep=$statusOrder[$booking['status']]??1;
$pageTitle='Pekerjaan #'.$bookingId;require '../includes/mechanic_header.php';
?>
<?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="success"><?=e($success)?></div><?php endif;?>
<div class="mechanic-service-head"><div><span class="muted">Workspace Mekanik / Detail pekerjaan</span><h2><?=e($booking['service_name'])?></h2><p><?=e($booking['plate_number'].' · '.$booking['brand'].' '.$booking['model'])?> · <?=e($booking['customer_name'])?></p></div><span class="badge badge-<?=$booking['status']?>"><?=e(status_label($booking['status']))?></span></div>
<div class="mechanic-service-summary"><div class="service-summary-card"><span>Harga layanan</span><strong><?=rupiah($booking['service_price'])?></strong><small>Harga dasar booking</small></div><div class="service-summary-card"><span>Sparepart</span><strong><?=rupiah($partsTotal)?></strong><small><?=count($parts)?> item digunakan</small></div><div class="service-summary-card highlight"><span>Estimasi total</span><strong><?=rupiah($grandTotal)?></strong><small>Layanan + sparepart</small></div><div class="service-summary-card"><span>Jadwal</span><strong><?=e(date('d M Y',strtotime($booking['booking_date'])))?></strong><small><?=e(date('H:i',strtotime($booking['booking_date'])))?> WIB</small></div></div>
<section class="panel mechanic-service-progress"><div class="panel-heading"><div><span class="muted">Progress pekerjaan</span><h2>Alur Servis</h2></div><span class="mechanic-progress-status"><?=e(status_label($booking['status']))?></span></div><div class="mechanic-progress-track"><?php foreach($statusSteps as $idx=>$step):$stepNo=$idx+1;$done=$currentStep>$stepNo;$active=$currentStep===$stepNo;?><div class="mechanic-progress-step <?=$done?'done':''?> <?=$active?'active':''?>"><span><?=$done?'✓':$stepNo?></span><strong><?=e($step[1])?></strong></div><?php if($idx<count($statusSteps)-1):?><i class="<?=$currentStep>$stepNo?'done':''?>"></i><?php endif;?><?php endforeach;?></div></section>
<div class="two-column mechanic-service-columns"><section class="panel"><div class="panel-heading"><h2>Detail Kendaraan</h2></div><dl class="detail-list"><dt>Customer</dt><dd><?=e($booking['customer_name'])?> · <?=e($booking['phone']?:'-')?></dd><dt>Kendaraan</dt><dd><?=e($booking['plate_number'].' · '.$booking['brand'].' '.$booking['model'].' · '.$booking['year'])?></dd><dt>Layanan</dt><dd><?=e($booking['service_name'])?> (<?=rupiah($booking['service_price'])?>)</dd><dt>Jadwal</dt><dd><?=e(date('d-m-Y H:i',strtotime($booking['booking_date'])))?></dd><dt>Keluhan</dt><dd><?=nl2br(e($booking['complaint']?:'-'))?></dd></dl></section>
<section class="panel"><div class="panel-heading"><div><span class="muted">Catatan teknis</span><h2>Pemeriksaan & Pengerjaan</h2></div><?php if(!$editable):?><span class="badge badge-paid">Read only</span><?php endif;?></div><?php if($editable):?><form method="post" class="compact-form"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="booking_id" value="<?=$bookingId?>"><label>Pemeriksaan<textarea name="inspection" rows="4"><?=e($record['inspection']??'')?></textarea></label><label>Diagnosis<textarea name="diagnosis" rows="4"><?=e($record['diagnosis']??'')?></textarea></label><label>Tindakan Servis<textarea name="action_taken" rows="4"><?=e($record['action_taken']??'')?></textarea></label><label>Catatan<textarea name="notes" rows="3"><?=e($record['notes']??'')?></textarea></label><button type="submit">Simpan Catatan</button></form><?php else:?><dl class="detail-list"><dt>Pemeriksaan</dt><dd><?=nl2br(e($record['inspection']??'-'))?></dd><dt>Diagnosis</dt><dd><?=nl2br(e($record['diagnosis']??'-'))?></dd><dt>Tindakan</dt><dd><?=nl2br(e($record['action_taken']??'-'))?></dd><dt>Catatan</dt><dd><?=nl2br(e($record['notes']??'-'))?></dd><?php if(!empty($record['completed_at'])):?><dt>Selesai pada</dt><dd><?=e(date('d-m-Y H:i',strtotime($record['completed_at'])))?></dd><?php endif;?></dl><?php endif;?></section></div>
<section class="panel"><div class="panel-heading"><div><span class="muted">Inventory pekerjaan</span><h2>Sparepart yang Digunakan</h2></div><strong class="service-total-inline"><?=rupiah($partsTotal)?></strong></div><?php if($editable && $spares):?><form method="post" class="compact-inline"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_part"><input type="hidden" name="booking_id" value="<?=$bookingId?>"><select name="sparepart_id" required><option value="">Pilih sparepart</option><?php foreach($spares as $p):?><option value="<?=$p['id']?>"><?=e($p['name'].' · stok '.$p['stock'].' · '.rupiah($p['price']))?></option><?php endforeach;?></select><input type="number" name="quantity" min="1" value="1" required><button type="submit">Tambah</button></form><?php elseif($editable):?><div class="mechanic-empty-state"><strong>Sparepart belum tersedia</strong><span>Belum ada stok aktif yang dapat digunakan.</span></div><?php endif;?><div class="table-wrap"><table class="data-table"><tr><th>Part</th><th>Qty</th><th>Harga</th><th>Total</th><th></th></tr><?php foreach($parts as $p):$line=$p['quantity']*$p['price'];?><tr><td><?=e($p['name'])?><small><?=e($p['part_number']?:'-')?></small></td><td><?=$p['quantity']?></td><td><?=rupiah($p['price'])?></td><td><?=rupiah($line)?></td><td><?php if($editable):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="remove_part"><input type="hidden" name="part_id" value="<?=$p['id']?>"><button class="small danger" type="submit">Hapus</button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$parts):?><tr><td colspan="5" class="muted center">Belum ada sparepart yang ditambahkan.</td></tr><?php endif;?><tr><th colspan="3">Total Sparepart</th><th><?=rupiah($partsTotal)?></th><th></th></tr></table></div></section>
<?php if($editable):?><section class="panel action-bar mechanic-complete-bar"><div><strong>Sudah selesai dikerjakan?</strong><span>Pastikan catatan teknis sudah tersimpan. Setelah selesai, pekerjaan masuk ke tahap pembayaran customer.</span></div><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="complete"><input type="hidden" name="booking_id" value="<?=$bookingId?>"><button type="submit" class="success-button" onclick="return confirm('Tandai pekerjaan selesai?')">Selesaikan Pekerjaan</button></form></section><?php elseif($booking['status']==='waiting_payment'):?><section class="mechanic-complete-bar closed"><strong>Pekerjaan selesai.</strong><span>Customer sekarang dapat melanjutkan proses pembayaran dan verifikasi admin.</span></section><?php endif;?>
